 import { supabase } from '../lib/supabase';

const YOCO_PUBLIC_KEY = process.env.REACT_APP_YOCO_PUBLIC_KEY;

// ============================================
// ✅ YOCO REDIRECT PAYMENT (No SDK needed - works 100%)
// ============================================
export async function initiatePayment({
  amount,
  currency = 'ZAR',
  email,
  fullName,
  userId,
  communityId = null,
  type = 'community',
  metadata = {}
}) {
  try {
    // 1. Calculate fees
    const platformFee = type === 'community' ? amount * 0.30 : amount * 0.10;
    const creatorEarnings = type === 'community' ? amount * 0.70 : amount * 0.90;

    // 2. Create pending record in Supabase
    const { data: payment, error } = await supabase
      .from('subscription_payments')
      .insert({
        user_id: userId,
        community_id: communityId,
        amount: amount,
        currency: currency,
        platform_fee: platformFee,
        creator_earnings: creatorEarnings,
        type: type,
        status: 'pending'
      })
      .select()
      .single();

    if (error) throw error;

    // 3. Build the Yoco Checkout URL manually
    // This is the same URL that the popup would load, just opened directly
    const checkoutUrl = `https://checkout.yoco.com/checkout?key=${YOCO_PUBLIC_KEY}`;
    
    // 4. You cannot pass metadata via the URL easily, 
    // so we just rely on the Supabase record we already created.

    // 5. Redirect the user to the Yoco payment page
    window.location.href = checkoutUrl;

    return { success: true, paymentId: payment.id };

  } catch (error) {
    console.error('Yoco payment error:', error);
    return { success: false, error: error.message };
  }
}
